import { test, expect } from '@playwright/test';

test.describe('Search Results Sorting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should sort search results by relevance, price, or date', async ({ page }) => {
    // Search for a product
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('laptop');

    // Wait for search results to load
    await page.waitForResponse(response => response.url().includes('/api/search'));

    // Verify search results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify at least one result exists
    const resultItems = page.getByRole('listitem', { name: /laptop/i });
    await expect(resultItems).toHaveCount(1);

    // Sort by relevance (default)
    const relevanceSortButton = page.getByRole('button', { name: /relevance/i });
    await expect(relevanceSortButton).toBeVisible();
    await relevanceSortButton.click();

    // Verify results are sorted by relevance
    const firstResult = page.getByRole('listitem', { name: /laptop/i }).first();
    await expect(firstResult).toBeVisible();

    // Sort by price
    const priceSortButton = page.getByRole('button', { name: /price/i });
    await expect(priceSortButton).toBeVisible();
    await priceSortButton.click();

    // Verify results are sorted by price
    const priceSortedResults = page.getByRole('listitem', { name: /laptop/i });
    const firstPriceResult = priceSortedResults.first();
    const secondPriceResult = priceSortedResults.nth(1);
    const firstPricePrice = await firstPriceResult.getByText(/\$\d+/).first().textContent();
    const secondPrice = await secondPriceResult.getByText(/\$\d+/).first().textContent();
    expect(parseFloat(firstPrice)).toBeLessThan(parseFloat(secondPrice));

    // Sort by date
    const dateSortButton = page.getByRole('button', { name: /date/i });
    await expect(dateSortButton).toBeVisible();
    await dateSortButton.click();

    // Verify results are sorted by date
    const dateSortedResults = page.getByRole('listitem', { name: /laptop/i });
    const firstDateResult = dateSortedResults.first();
    const secondDateResult = dateSortedResults.nth(1);
    const firstDateText = await firstDateResult.getByText(/\d{2,}/).first().textContent();
    const secondDateText = await secondDateResult.getByText(/\d{2,}/).first().textContent();
    expect(firstDateText).not.toBe(secondDateText);
  });

  test('should handle sorting when no results are found', async ({ page }) => {
    // Search for a non-existent product
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('xyz123nonexistentproduct');

    // Wait for search results to load
    await page.waitForResponse(response => response.url().includes('/api/search'));

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify sort buttons are disabled or not visible
    const relevanceSortButton = page.getByRole('button', { name: /relevance/i });
    await expect(relevanceSortButton).not.toBeVisible();

    const priceSortButton = page.getByRole('button', { name: /price/i });
    await expect(priceSortButton).not.toBeVisible();

    const dateSortButton = page.getByRole('button', { name: /date/i });
    await expect(dateSortButton).not.toBeVisible();
  });
});
